{"sql": "WITH q2 AS (
  SELECT o.order_id FROM orders o
  WHERE o.order_purchase_timestamp >= '2018-04-01' AND o.order_purchase_timestamp < '2018-07-01'
),
multi AS (
  SELECT p.order_id, count(*) AS n, sum(p.payment_value) AS pv
  FROM order_payments p JOIN q2 USING(order_id) GROUP BY p.order_id HAVING count(*) > 1
)
SELECT count(*) AS multi_row_orders, sum(n) AS multi_row_payment_rows, sum(pv) AS multi_row_payment_value
FROM multi;"}
